-- columns of financial tables
SELECT table_name,column_name,data_type,numeric_precision,numeric_scale,is_nullable,column_default
FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('orders','order_items','payments','order_item_cancellations','order_status_history','order_stock_reservations','products','inventory','inventory_movements','accounting_inventory_movement_events','customers_accounting','suppliers','invoices_customer','invoice_customer_lines','invoices_supplier','invoice_supplier_lines','payments_made','payments_received','chart_of_accounts','journal_entries','journal_entry_lines','general_ledger','bank_accounts_ledger','bank_reconciliation_lines','bank_reconciliation_sessions','salaries','employees','employment_contracts','accounting_event_outbox','accounting_event_redrive_audit','audit_export_logs','report_export_audit_logs','product_audit_log','fiscal_periods','tax_periods','restaurant_settings','auto_posting_rules','recurring_journal_templates','fixed_assets','exchange_rates','account_budgets','supplier_payment_schedules','e_invoice_submissions','restaurants','tenants','permission_audit_logs','hr_audit_logs')
ORDER BY table_name,ordinal_position;
